UPDATE openbiz_shop_inventory
SET quantity = #{quantity}, version = version + 1, update_time = NOW()
WHERE product_id = #{productId} AND tenant_id = #{tenantId} AND version = #{version}

UPDATE openbiz_shop_inventory
SET quantity = quantity - #{qty}, version = version + 1, update_time = NOW()
WHERE product_id = #{productId}
  AND tenant_id = #{tenantId}
  AND version = #{version}
  AND quantity >= #{qty}
